function add_filter($hook,$callback,$priority=10,$args=1){add_action($hook,$callback,$priority,$args);}
function wp_next_scheduled($hook){return $GLOBALS['invitation_schedule'][$hook]??false;}
function wp_schedule_single_event($time,$hook){$GLOBALS['invitation_schedule'][$hook]=$time;return true;}
