function home_url($path=''){return 'https://school.test'.$path;}
function add_query_arg($args,$value=null,$url=null){if(is_array($args))$url=$value;else $args=[$args=>$value];return $url.(str_contains($url,'?')?'&':'?').http_build_query($args);}
function get_password_reset_key($u){$key=bin2hex(random_bytes(20));$GLOBALS['invitation_keys'][$u->ID]=['hash'=>hash('sha256',$key),'time'=>time()];wp_update_user(['ID'=>$u->ID,'user_activation_key'=>hash('sha256',$key)]);return $key;}
function check_password_reset_key($key,$login){$id=username_exists($login);$row=$GLOBALS['invitation_keys'][$id]??[];return isset($row['hash'])&&$GLOBALS['wpdb']->pdo->query('SELECT user_activation_key FROM mock_users WHERE ID='.(int)$id)->fetchColumn()!==''&&hash_equals($row['hash'],hash('sha256',$key))&&time()-$row['time']<86400?get_userdata((int)$id):new WP_Error('expired_key','Expirado');}
function wp_set_password($password,$id){global $wpdb;$wpdb->update('mock_users',['user_pass'=>$password],['ID'=>$id]);unset($GLOBALS['invitation_keys'][$id]);do_action('wp_set_password',$password,$id);}
function sanitize_text_field($s){return strip_tags(trim($s));}
function user_can($user,$cap){foreach($user->roles as $role)if(!empty($GLOBALS['test_roles'][$role]['capabilities'][$cap]))return true;return false;}
function is_super_admin($id){return $id===1;}
